import Foundation
import Testing

enum BasisTextureFixture {
    enum Encoding: CaseIterable, Sendable { case etc1s, uastc, uastcZstd }

    // Eight-by-eight RGBA quadrant texture generated from test-authored pixels with
    // Basis Universal 2.50. Each file stores four mips. No third-party image data.
    static func data(_ encoding: Encoding) throws -> Data {
        let encoded = switch encoding {
        case .etc1s: ""
        case .uastc: ""
        case .uastcZstd: ""
        }
        return try #require(Data(base64Encoded: encoded))
    }

    /// Center texels from the upstream 2.50 CLI's RGBA32 unpacked PNGs.
    static func centerTexels(_ encoding: Encoding) -> [SIMD4<UInt8>] {
        switch encoding {
        case .etc1s:
            [SIMD4(222, 206, 32, 255), SIMD4(203, 195, 162, 236), SIMD4(177, 177, 128, 225), SIMD4(153, 145, 120, 160)]
        case .uastc, .uastcZstd:
            [SIMD4(220, 205, 35, 255), SIMD4(221, 204, 68, 255), SIMD4(187, 187, 102, 221), SIMD4(156, 144, 124, 160)]
        }
    }

    static func corruptZstd(_ data: Data) -> Data {
        var output = data
        let baseLevelOffset = data.withUnsafeBytes {
            Int(UInt64(littleEndian: $0.loadUnaligned(fromByteOffset: 80, as: UInt64.self)))
        }
        output[baseLevelOffset] = 0
        return output
    }
}
